let tendenz = 'UNKLAR', grund = 'Fahrzeugwert unbekannt – Entscheidung nach Werkstattprüfung.';
if (wertMitte) {
  const quote = kosten.gesamt_max / wertMitte;
  kosten.quote_reparatur_zu_wert = Math.round(quote * 100) / 100;
  if (quote < 0.3) { tendenz = 'REPARIEREN'; grund = `Maximale Reparaturkosten (${kosten.gesamt_max} €) liegen unter 30 % des geschätzten Fahrzeugwerts.`; }
  else if (quote <= 0.7) { tendenz = 'ABWAEGEN'; grund = `Reparaturkosten bis ${kosten.gesamt_max} € entsprechen ${Math.round(quote * 100)} % des Fahrzeugwerts – Kostenvoranschlag einholen.`; }
  else { tendenz = 'VERKAUF_ERWAEGEN'; grund = `Reparaturkosten bis ${kosten.gesamt_max} € liegen über 70 % des geschätzten Fahrzeugwerts.`; }
}
s.schaetzung = { ...kosten, fahrzeugwert_min: k.fahrzeugwert_min_eur, fahrzeugwert_max: k.fahrzeugwert_max_eur, empfehlung: tendenz, begruendung: grund, regel: '<30 % reparieren · 30–70 % abwägen · >70 % Verkauf erwägen', hinweis: 'Unverbindliche Schätzung. Die Entscheidung trifft der Fahrzeugbesitzer nach Prüfung durch die Werkstatt.' };

