s.tokens_gesamt = auf.every(a => a.total_tokens !== null) ? auf.reduce((a, x) => a + x.total_tokens, 0) : null;
s.kosten_usd = auf.length && auf.every(a => a.kosten_usd !== null) ? auf.reduce((a, x) => a + x.kosten_usd, 0) : null;
return [{ json: s }];

