  sec('Terminvorschläge (' + s.kalender.quelle + ')', s.kalender.vorschlaege.length ? s.kalender.vorschlaege.map(v => v.text + ` (${s.kalender.dauer_stunden} h)`) : ['Keine freien Termine gefunden']);
