  if (k.sprache_kunde.toLowerCase() !== 'deutsch') { T.push('', 'Übersetzung:', k.antwort_kunde_de); H.push(`<p style="color:#555"><b>Übersetzung:</b> ${esc(k.antwort_kunde_de)}</p>`); }
  if (s.eingabe.kunden_email) { T.push('', 'Kunden-E-Mail: ' + s.eingabe.kunden_email); H.push(`<p>Kunden-E-Mail: ${esc(s.eingabe.kunden_email)}</p>`); }
}
if (s.errors.length) sec('Technische Fehler', s.errors.map(e => `${e.quelle} / ${e.code}: ${e.nachricht}`));
