s.bericht_text = T.join('\n');
const farbe = s.status === 'ABGESCHLOSSEN' ? '#2A9D8F' : s.status === 'TEILERGEBNIS' ? '#F2A007' : '#D9534F';
s.bericht_html = `<div style="font-family:Arial,sans-serif;max-width:720px;color:#1B1F2A">
<div style="background:#14213D;color:#fff;padding:16px 20px;border-radius:8px 8px 0 0"><div style="font-size:12px;color:#F2A007">AUTOSCAN AI · WERKSTATTANFRAGE</div><div style="font-size:20px;font-weight:bold">${esc(fz)}</div>
<span style="display:inline-block;margin-top:6px;background:${farbe};padding:2px 10px;border-radius:10px;font-size:12px">${s.status}</span></div>
<div style="border:1px solid #D5DAE3;border-top:0;padding:4px 20px 16px;border-radius:0 0 8px 8px">${H.join('\n')}
