if (!s.email_senden) s.email_status = !s.gueltig ? 'NICHT_GESENDET_EINGABEFEHLER' : !s.config.email_aktiv ? 'DEAKTIVIERT' : 'KEIN_EMPFAENGER';
else if (r.error) { s.email_status = 'FEHLER'; s.errors.push({ quelle: 'E-Mail', code: 'VERSANDFEHLER', nachricht: 'Gmail: ' + (typeof r.error === 'string' ? r.error : r.error.message ?? 'Fehler') }); if (s.status === 'ABGESCHLOSSEN') s.status = 'TEILERGEBNIS'; }
