const s = JSON.parse(JSON.stringify($('24 Versandstatus').first().json));
// Gemeinsame Auswertung einer HTTP-Antwort (fullResponse + neverError)
const parseHttp = (raw, name) => {
  if (raw?.error) { const m = typeof raw.error === 'string' ? raw.error : (raw.error.message || JSON.stringify(raw.error)); throw { code: /timeout|timed out|ETIMEDOUT|ECONNABORTED/i.test(m) ? 'TIMEOUT' : 'VERBINDUNGSFEHLER', message: name + ': ' + m }; }
  const status = Number(raw?.statusCode ?? 200);
  if ([401, 403].includes(status)) throw { code: 'AUTH_FEHLER', message: name + ': HTTP ' + status + ' – Zugang prüfen.' };
  if (status === 429) throw { code: 'RATE_LIMIT', message: name + ': HTTP 429 – zu viele Anfragen.' };
  let b = raw?.body ?? raw;
  if (typeof b === 'string') { if (!b.trim()) b = null; else { try { b = JSON.parse(b); } catch { if (status >= 300) throw { code: 'HTTP_FEHLER', message: name + ': HTTP ' + status }; } } }
  if (status < 200 || status >= 300) throw { code: 'HTTP_FEHLER', message: name + ': HTTP ' + status + (b?.error?.message ? ' – ' + b.error.message : '') };
  return { status, body: b };
};

try { parseHttp($('25 Lauf in Supabase speichern').first().json, 'Supabase Lauf'); s.db_status = 'GESPEICHERT'; }
catch (e) { s.db_status = 'FEHLER'; s.errors.push({ quelle: 'Supabase', code: e.code || 'DB_FEHLER', nachricht: e.message || String(e) }); }
